-- Real database authorization, metadata privacy, role and configuration tests.
begin;
create function pg_temp.ok(value boolean,label text) returns void language plpgsql as $$
begin if value is distinct from true then raise exception 'FAIL: %',label; end if; end $$;
create function pg_temp.rejects(statement text) returns boolean language plpgsql as $$
begin execute statement; return false;
exception when insufficient_privilege or invalid_parameter_value or no_data_found or check_violation or unique_violation then return true;
end $$;
insert into auth.users(id) values ('11111111-1111-4111-8111-111111111111'),('22222222-2222-4222-8222-222222222222'),('33333333-3333-4333-8333-333333333333');
update public.user_roles set role='admin' where user_id='33333333-3333-4333-8333-333333333333';
set local role anon;
select pg_temp.ok(pg_temp.rejects('select public.admin_list_users()'),'anonymous user administration');
reset role;
set local role authenticated;
select set_config('request.jwt.claim.sub','11111111-1111-4111-8111-111111111111',true);
select set_config('request.jwt.claims','{"sub":"11111111-1111-4111-8111-111111111111","role":"authenticated"}',true);
select pg_temp.ok(pg_temp.rejects('select public.admin_list_users()'),'user list denied');
select pg_temp.ok(pg_temp.rejects('select public.admin_generated_metadata()'),'support view denied');
select pg_temp.ok(pg_temp.rejects($q$select public.admin_set_user_role(auth.uid(),'admin')$q$),'self escalation denied');
select pg_temp.ok(pg_temp.rejects($q$select public.admin_remove_configuration('card_images',gen_random_uuid())$q$),'configuration delete denied');
select pg_temp.ok(pg_temp.rejects($q$select public.admin_asset_deletable('private-path.png')$q$),'asset references denied to regular users');
select pg_temp.ok(pg_temp.rejects($q$insert into public.cards(title,slug) values ('Forbidden','__forbidden')$q$),'direct catalog write denied');
select pg_temp.ok(pg_temp.rejects($q$insert into storage.objects(bucket_id,name) values ('card-assets','__forbidden.png')$q$),'direct asset write denied');
select set_config('request.jwt.claim.sub','33333333-3333-4333-8333-333333333333',true);
select set_config('request.jwt.claims','{"sub":"33333333-3333-4333-8333-333333333333","role":"authenticated"}',true);
select pg_temp.ok(pg_temp.rejects($q$select public.admin_set_user_role(auth.uid(),'user')$q$),'admin self demotion denied');
select public.admin_set_user_role('22222222-2222-4222-8222-222222222222','admin');
select pg_temp.ok((select role='admin' from jsonb_to_recordset(public.admin_list_users()) as u(id uuid,role text) where id='22222222-2222-4222-8222-222222222222'),'authorized role assignment');
select pg_temp.ok(not exists(select 1 from jsonb_array_elements(public.admin_list_users()) u where u ?| array['encrypted_password','password','confirmation_token','raw_app_meta_data']),'no authentication secrets');
select pg_temp.ok(not exists(select 1 from jsonb_array_elements(public.admin_generated_metadata()) u where u ?| array['personalization_data','generated_text','template_snapshot','output_image_path','error_message']),'support metadata projection');
create temp table fixtures(key text primary key,id uuid);
insert into fixtures values ('card',(public.admin_save_card_data('cards','{"title":"Admin fixture","slug":"__admin_fixture","status":"draft"}')->>'id')::uuid);
select pg_temp.ok(pg_temp.rejects($q$select public.admin_save_card_data('cards','{"status":"published"}',(select id from fixtures where key='card'))$q$),'available publication requires a template');
insert into fixtures values ('template',(public.admin_save_card_data('card_templates',jsonb_build_object('card_id',(select id from fixtures where key='card'),'template_key','__admin_template','layout_config','{}'::jsonb))->>'id')::uuid);
select public.admin_save_card_data('cards','{"status":"published"}',(select id from fixtures where key='card'));
insert into fixtures values ('first',(public.admin_save_card_data('personalization_fields',jsonb_build_object('card_id',(select id from fixtures where key='card'),'field_key','first','label','First','field_type','text'))->>'id')::uuid);
insert into fixtures values ('second',(public.admin_save_card_data('personalization_fields',jsonb_build_object('card_id',(select id from fixtures where key='card'),'field_key','second','label','Second','field_type','text'))->>'id')::uuid);
select public.admin_reorder_fields((select id from fixtures where key='card'),array[(select id from fixtures where key='second'),(select id from fixtures where key='first')]);
select pg_temp.ok((select sort_order=0 from public.personalization_fields where id=(select id from fixtures where key='second')),'field reorder');
select pg_temp.ok(pg_temp.rejects($q$select public.admin_reorder_fields((select id from fixtures where key='card'),array[(select id from fixtures where key='first'),gen_random_uuid()])$q$),'mixed card reorder rejected');
select pg_temp.ok(pg_temp.rejects($q$select public.admin_save_card_data('cards','{"title":" ","slug":"__blank"}')$q$),'blank required fields');
select pg_temp.ok(pg_temp.rejects($q$select public.admin_save_card_data('personalization_fields',jsonb_build_object('card_id',(select id from fixtures where key='card'),'field_key','first','label','Duplicate','field_type','text'))$q$),'duplicate field key');
select pg_temp.ok(pg_temp.rejects($q$select public.admin_save_card_data('card_templates','{"layout_config":{"regions":[{"x":-1}]}}',(select id from fixtures where key='template'))$q$),'invalid layout region');
select public.admin_save_card_data('card_templates','{"layout_config":{"image_regions":[{"storage_path":"__admin/historical.png","optional":true}]}}',(select id from fixtures where key='template'));
insert into storage.objects(bucket_id,name) values ('card-assets','__admin/historical.png'),('card-assets','__admin/unreferenced.png');
select pg_temp.ok((select version=2 from public.card_templates where id=(select id from fixtures where key='template')),'template version increment');
select public.admin_save_card_data('card_templates','{"layout_config":{}}',(select id from fixtures where key='template'));
select pg_temp.ok(private.asset_is_referenced('__admin/historical.png'),'historical file is protected by deletion predicate');
select pg_temp.ok(not private.asset_is_referenced('__admin/unreferenced.png'),'unreferenced file is eligible for Storage API deletion');
select public.admin_remove_configuration('personalization_fields',(select id from fixtures where key='first'));
select pg_temp.ok((select count(*)=0 from public.personalization_fields where id=(select id from fixtures where key='first')),'field removal');
reset role;
update public.user_roles set role='user' where user_id='33333333-3333-4333-8333-333333333333';
set local role authenticated;
select pg_temp.ok(pg_temp.rejects('select public.admin_list_users()'),'revoked admin immediately denied');
reset role;
select 'Admin authorization and integrity checks passed; fixtures rolled back.' as result;
rollback;
